(function() {
    tinymce.PluginManager.add('cleanhtml', function(editor, url) {
        var svgIcon = '<svg width="18" height="18" viewBox="0 -64 640 640" fill="currentColor" focusable="false" style="display:block;margin:auto;"><path d="M336 416h-11.17l9.26-27.77L267 336.4 240.49 416H208a16 16 0 0 0-16 16v32a16 16 0 0 0 16 16h128a16 16 0 0 0 16-16v-32a16 16 0 0 0-16-16m297.82 42.1L377 259.59 426.17 112H544v32a16 16 0 0 0 16 16h32a16 16 0 0 0 16-16V48a16 16 0 0 0-16-16H176a16 16 0 0 0-16 16v43.9L45.46 3.38A16 16 0 0 0 23 6.19L3.37 31.46a16 16 0 0 0 2.81 22.45l588.36 454.72a16 16 0 0 0 22.46-2.81l19.64-25.27a16 16 0 0 0-2.82-22.45M309.91 207.76 224 141.36V112h117.83z"/></svg>';

        editor.addButton('cleanhtml', {
            title: 'Clean HTML',
            icon: 'cleanhtml-custom-icon',
            onPostRender: function() {
                var btn = this;
                var iconEl = btn.$el.find('.mce-ico');
                if (iconEl && iconEl.length) {
                    iconEl.html(svgIcon);
                }
            },
            onclick: function() {
                try {
                    var content = editor.getContent();
                    if (!content || !content.trim()) {
                        return;
                    }

                    // 1. Remove Zero-width characters & normalize Unicode whitespace (ChatGPT, Claude, Gemini, DeepSeek)
                    content = content.replace(/[\u200B\u200C\u200D\uFEFF\u2060\u180E]/g, '');
                    content = content.replace(/[\u00A0\u2000-\u200A\u202F\u205F\u3000]/g, ' ');
                    content = content.replace(/&nbsp;/gi, ' ');
                    content = content.replace(/&#160;/gi, ' ');

                    // 2. Remove markdown code-fence leftovers (e.g. ```html or ```)
                    content = content.replace(/^```[a-z0-9_-]*\s*$/gim, '');

                    // 3. Helper to unwrap an element (replace element with its child nodes)
                    function unwrap(el) {
                        var parent = el.parentNode;
                        if (!parent) return;
                        while (el.firstChild) {
                            parent.insertBefore(el.firstChild, el);
                        }
                        parent.removeChild(el);
                    }

                    // Helper to check if node is a block element
                    function isBlockElement(el) {
                        return el && /^(P|H[1-6]|UL|OL|LI|DIV|BLOCKQUOTE|TABLE|PRE|FIGURE|HR|HEADER|FOOTER|SECTION|ARTICLE)$/i.test(el.tagName);
                    }

                    // 4. Parse DOM
                    var tempDiv = document.createElement('div');
                    tempDiv.innerHTML = content;

                    // AI class patterns to strip
                    var aiClassRegex = /^(ng-star-inserted|citation(-\w+)?|citation-end(-\w+)?|markdown(-[\w-]+)?|md-[\w-]+|enable-[\w-]+|stronger|prose(-[\w-]+)?|dark:[\w-]+|ds-[\w-]+|ant-[\w-]+|claude-[\w-]+|chat-[\w-]+|model-response-[\w-]+)$/i;

                    // A. Strip unwanted attributes & AI classes across all elements
                    var allElements = tempDiv.querySelectorAll('*');
                    allElements.forEach(function(el) {
                        var attrs = Array.from(el.attributes);
                        attrs.forEach(function(attr) {
                            var name = attr.name.toLowerCase();
                            // Remove all data-* attributes, aria-*, and AI-generated attributes
                            if (name.indexOf('data-') === 0 ||
                                name.indexOf('aria-') === 0 ||
                                name === 'contenteditable' ||
                                name === 'spellcheck' ||
                                name === 'tabindex' ||
                                name === 'dir' ||
                                (name === 'id' && /^(model-response|chat|message|prose|__)/i.test(attr.value))
                            ) {
                                el.removeAttribute(attr.name);
                            }
                        });

                        // Filter AI classes
                        if (el.className && typeof el.className === 'string') {
                            var classes = el.className.split(/\s+/).filter(function(cls) {
                                return cls && !aiClassRegex.test(cls);
                            });
                            if (classes.length > 0) {
                                el.className = classes.join(' ');
                            } else {
                                el.removeAttribute('class');
                            }
                        }
                    });

                    // B. Unwrap useless container DIVs inside <li>
                    tempDiv.querySelectorAll('li > div').forEach(function(div) {
                        unwrap(div);
                    });

                    // C. Unwrap empty/clean SPANs and useless formatting wrappers
                    tempDiv.querySelectorAll('span').forEach(function(span) {
                        // If span has no attributes remaining, unwrap it
                        if (!span.attributes.length) {
                            unwrap(span);
                        } else if (!span.textContent.trim() && !span.children.length) {
                            span.remove();
                        }
                    });

                    // D. Unwrap outer AI wrapper DIVs (e.g. model-response-message-content, md-content, etc.)
                    // Convert standalone DIVs containing text or inline tags into <p> tags
                    tempDiv.querySelectorAll('div').forEach(function(div) {
                        if (!div.parentNode) return;

                        var hasBlockChild = div.querySelector('p, h1, h2, h3, h4, h5, h6, ul, ol, table, blockquote, pre');
                        if (hasBlockChild) {
                            // Container div holding block elements -> unwrap div
                            unwrap(div);
                        } else if (!div.attributes.length || (div.attributes.length === 1 && div.className === '')) {
                            // Plain div holding inline text -> convert to <p> if it has text or media
                            if (div.textContent.trim() || div.querySelector('img, iframe, video, audio, svg')) {
                                var p = document.createElement('p');
                                while (div.firstChild) {
                                    p.appendChild(div.firstChild);
                                }
                                div.parentNode.replaceChild(p, div);
                            } else {
                                div.remove();
                            }
                        }
                    });

                    // E. Remove redundant BR elements adjacent to block elements (e.g., </p><br /><p>)
                    tempDiv.querySelectorAll('br').forEach(function(br) {
                        var prev = br.previousElementSibling;
                        var next = br.nextElementSibling;
                        if (isBlockElement(prev) || isBlockElement(next)) {
                            br.remove();
                        }
                    });

                    // F. Remove empty elements & isolated tags
                    tempDiv.querySelectorAll('p, h1, h2, h3, h4, h5, h6, b, strong, i, em, u, s').forEach(function(el) {
                        if (!el.textContent.trim() && !el.querySelector('img, iframe, video, audio, table, svg, input')) {
                            el.remove();
                        }
                    });

                    // G. Clean multi-spaces & space before punctuation in text nodes (excluding pre/code)
                    var walker = document.createTreeWalker(tempDiv, NodeFilter.SHOW_TEXT, null, false);
                    var textNode;
                    while ((textNode = walker.nextNode())) {
                        var parentTag = textNode.parentElement ? textNode.parentElement.tagName.toLowerCase() : '';
                        if (parentTag === 'pre' || parentTag === 'code' || parentTag === 'script' || parentTag === 'style') {
                            continue;
                        }
                        var val = textNode.nodeValue;
                        // Collapse consecutive spaces/tabs
                        val = val.replace(/[ \t]{2,}/g, ' ');
                        // Fix spaces before punctuation (e.g. "word , text ." -> "word, text.")
                        val = val.replace(/\s+([\,\.\;\:\!\?])/g, '$1');
                        textNode.nodeValue = val;
                    }

                    // H. Final regex string cleanup for redundant <br> tags between/inside blocks
                    var blockPattern = 'p|h[1-6]|ul|ol|li|div|blockquote|table|pre|figure|header|footer|section|article';
                    var blockRegexBetween = new RegExp('(</(?:' + blockPattern + ')>)\\s*(?:<br\\s*/?>\\s*)+(<(?:' + blockPattern + ')\\b)', 'gi');
                    var blockRegexStart = new RegExp('(<(?:' + blockPattern + ')\\b[^>]*>)\\s*(?:<br\\s*/?>\\s*)+', 'gi');
                    var blockRegexEnd = new RegExp('(?:<br\\s*/?>\\s*)+(</(?:' + blockPattern + ')>)', 'gi');

                    var cleanedContent = tempDiv.innerHTML
                        .replace(blockRegexBetween, '$1$2')
                        .replace(blockRegexStart, '$1')
                        .replace(blockRegexEnd, '$1')
                        .replace(/(?:<br\s*\/?>\s*){2,}/gi, '<br>')
                        .replace(/<p>\s*(?:<br\s*\/?>\s*)*<\/p>/gi, '')
                        .replace(/^(?:\s*<br\s*\/?>\s*)+|(?:\s*<br\s*\/?>\s*)+$/gi, '')
                        .trim();

                    // Apply back to editor
                    if (typeof jQuery !== 'undefined' && jQuery('#wp-content-wrap').hasClass('html-active')) {
                        jQuery('#content').val(cleanedContent);
                    } else {
                        editor.setContent(cleanedContent);
                    }

                    if (editor.notificationManager) {
                        editor.notificationManager.open({
                            text: 'Clean HTML Successfully!',
                            type: 'success',
                            timeout: 2000
                        });
                    }
                } catch (e) {
                    console.error('Error in cleanhtml plugin:', e);
                    editor.windowManager.alert('An error occurred while cleaning HTML');
                }
            }
        });
    });
})();